/**
 ******************************************************************************
 * @file    fx_render.c
 * TEAM CODE (owner: Tom - sound output and effects) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Tom's sound output subsystem (best-ui), with an AI coding assistant;
 *          Brendon (integrator) added the carry, so a stopped effect file can be made again from the middle (30 Oct 2026, with an AI coding assistant).
 * @brief   Effect-file renderer: the old live effect chain, run offline.
 *
 * Pure: no RTOS, no HAL. Run by FxRenderTask (Core/Src/tom_fx_render.c),
 * one chunk per request from JackStorageTask; see fx_render.h for the steps,
 * and for why a file made again from the middle needs a pre-roll and the
 * carry (FxRender_SaveCarry / FxRender_LoadCarry, at the end of this file).
 *
 * The chain per 64-sample source block is the one TomTask ran live until
 * 29 Oct 2026 (tom_dac_output.c as it was then, lines 318-369):
 *   32 kHz source:  upsample 2:3 (64 -> 96 samples), then the effect on
 *                   the first 64 and then on the last 32 of them
 *   48 kHz source:  the effect on the 64 samples as they are
 * The split matters: some effects (Autotune, Robot) update their settings
 * once per call, so other call sizes would give slightly different sound.
 * The host tests check every effect sample for sample against a copy of
 * the old chain's upsampler and effect loop, run with today's effects
 * (Tests/OutputChain/test_fx_render.c).
 ******************************************************************************
 */
#include "fx_render.h"

#include <stdbool.h>
#include <stddef.h>
#include <string.h>

/** True for AUTOTUNE .. REVERB (the same test as AudioEffects_SetMode). */
static bool mode_is_valid(AudioEffectMode mode)
{
    return (mode >= AUDIO_EFFECT_AUTOTUNE) && (mode < AUDIO_EFFECT_COUNT);
}

/**
 * The effect on n samples at 48 kHz, in calls of at most 64 samples (for an
 * upsampled block of 96: 64, then 32). A call that fails is copied through
 * dry, as the live chain did; the first failure is returned.
 */
static AudioEffectsStatus run_effect(AudioEffectsState *effects,
                                     const int16_t *in_48k,
                                     uint32_t n,
                                     int16_t *out_48k)
{
    AudioEffectsStatus first_error = AUDIO_EFFECTS_STATUS_OK;
    uint32_t done = 0U;

    while (done < n)
    {
        uint32_t call_samples = n - done;
        if (call_samples > AUDIO_EFFECTS_MAX_BLOCK_SIZE)
        {
            call_samples = AUDIO_EFFECTS_MAX_BLOCK_SIZE;
        }

        const AudioEffectsStatus status = AudioEffects_ProcessBlock(effects, &in_48k[done],
                                                                    &out_48k[done], call_samples);
        if (status != AUDIO_EFFECTS_STATUS_OK)
        {
            memcpy(&out_48k[done], &in_48k[done], call_samples * sizeof(int16_t));
            if (first_error == AUDIO_EFFECTS_STATUS_OK)
            {
                first_error = status;
            }
        }
        done += call_samples;
    }
    return first_error;
}

/** One source block (at most 64 samples): upsample if 32 kHz, then the effect. */
static AudioEffectsStatus render_block(FxRender *render,
                                       const int16_t *in,
                                       uint32_t n_in,
                                       int16_t *out,
                                       uint32_t *n_out)
{
    if (!render->source_is_32k)
    {
        *n_out = n_in;
        return run_effect(&render->effects, in, n_in, out);
    }

    const uint32_t n_upsampled = RateAdapter2to3_Process(&render->upsampler, in, n_in, render->block_48k);
    *n_out = n_upsampled;
    return run_effect(&render->effects, render->block_48k, n_upsampled, out);
}

/*
 * Why Begin first clears the whole effect state: the effects' states share
 * one block of memory (the union in audio_effects.h), and Init, SetMode and
 * Reset clear only the chosen effect's own fields. The rest of that block (a
 * bigger effect's buffer, the padding bytes between fields) still holds what
 * the last file left there, for example Echo samples. After the clear, every
 * file starts exactly as in a fresh, all-zero FxRender, so no effect can
 * depend on bytes from the file made before it (the pitch shifter once read
 * 4 bytes just past its own buffer: see pitch_shifter.c).
 *
 * Why Begin calls AudioEffects_Init: the pitch presets (+7 semitones for
 * Pitch up, -7 for Pitch down) are set ONLY there. FxRenderTask's FxRender
 * is a zero-filled static that nobody else initialises, so without Init
 * every Pitch up / Pitch down file would be made at 0 semitones: not
 * shifted at all. Then SetMode and Reset, as TomTask did when an effect was
 * chosen and when playback started (the second Reset it did there changes
 * nothing more, so it is left out).
 */
AudioEffectsStatus FxRender_Begin(FxRender *render,
                                  AudioEffectMode mode,
                                  uint32_t source_rate_hz)
{
    if (render == NULL)
    {
        return AUDIO_EFFECTS_STATUS_NULL_POINTER;
    }
    if (!mode_is_valid(mode))
    {
        return AUDIO_EFFECTS_STATUS_INVALID_MODE;
    }
    if ((source_rate_hz != FX_RENDER_RATE_32K_HZ) && (source_rate_hz != FX_RENDER_RATE_48K_HZ))
    {
        return AUDIO_EFFECTS_STATUS_INVALID_PARAMETER;
    }

    memset(&render->effects, 0, sizeof(render->effects));  /* nothing of the last file is left */
    AudioEffects_Init(&render->effects);
    (void)AudioEffects_SetMode(&render->effects, mode);     /* mode checked above: cannot fail */
    AudioEffects_Reset(&render->effects);
    RateAdapter2to3_Reset(&render->upsampler);
    render->source_is_32k = (source_rate_hz == FX_RENDER_RATE_32K_HZ) ? 1U : 0U;
    return AUDIO_EFFECTS_STATUS_OK;
}

AudioEffectsStatus FxRender_Process(FxRender *render,
                                    const int16_t *in,
                                    uint32_t n_in,
                                    int16_t *out,
                                    uint32_t out_cap,
                                    uint32_t *n_out)
{
    if (n_out != NULL)
    {
        *n_out = 0U;
    }
    if ((render == NULL) || (in == NULL) || (out == NULL) || (n_out == NULL))
    {
        return AUDIO_EFFECTS_STATUS_NULL_POINTER;
    }
    if (in == out)
    {
        return AUDIO_EFFECTS_STATUS_BUFFER_ALIAS;
    }

    const uint32_t rate_hz = render->source_is_32k ? FX_RENDER_RATE_32K_HZ : FX_RENDER_RATE_48K_HZ;
    if (out_cap < FxRender_OutputSamples(n_in, rate_hz))
    {
        return AUDIO_EFFECTS_STATUS_INVALID_LENGTH;
    }

    /* Block by block, on the same 64-sample grid as the live chain. */
    AudioEffectsStatus first_error = AUDIO_EFFECTS_STATUS_OK;
    uint32_t done_in = 0U;
    uint32_t done_out = 0U;
    while (done_in < n_in)
    {
        uint32_t block_samples = n_in - done_in;
        if (block_samples > FX_RENDER_BLOCK_SAMPLES)
        {
            block_samples = FX_RENDER_BLOCK_SAMPLES;
        }

        uint32_t block_out = 0U;
        const AudioEffectsStatus status = render_block(render, &in[done_in], block_samples,
                                                       &out[done_out], &block_out);
        if (first_error == AUDIO_EFFECTS_STATUS_OK)
        {
            first_error = status;
        }
        done_in += block_samples;
        done_out += block_out;
    }

    *n_out = done_out;
    return first_error;
}

uint32_t FxRender_OutputSamples(uint32_t source_samples, uint32_t source_rate_hz)
{
    if (source_rate_hz == FX_RENDER_RATE_48K_HZ)
    {
        return source_samples;
    }
    if (source_rate_hz != FX_RENDER_RATE_32K_HZ)
    {
        return 0U;
    }

    const uint32_t whole_blocks = source_samples / FX_RENDER_BLOCK_SAMPLES;
    const uint32_t rest_samples = source_samples % FX_RENDER_BLOCK_SAMPLES;
    return (whole_blocks * FX_RENDER_UPSAMPLED_BLOCK_SAMPLES) + ((3U * rest_samples) / 2U);
}

/* ======================================================================= */
/* TEAM CODE (written by Brendon, 30 Oct 2026): the carry                   */
/* ======================================================================= */
/*
 * The carry is the few numbers of an effect's state that a pre-roll cannot
 * rebuild, because they never forget (fx_render.h explains the pre-roll).
 * A grain phase, for example: where the shifter's read heads are in their
 * grains depends on every sample since the file started, so a pre-roll of
 * 64 ms would leave them somewhere else, and the rest of the file would
 * sound the same but not be the same samples. These functions only COPY
 * fields of Tom's effect state; no effect's sound changes.
 */

#define FX_RENDER_CARRY_LABEL 0xCAU     /* the first byte of every saved carry ("CArry"); 0 = no carry */

/** What Autotune never forgets (32 B). Not carried: the shifter's
 *  current_ratio and target_ratio, which hard tune sets from ratio_target
 *  in every block, and everything the 64 ms pre-roll refills (the detector,
 *  the look-ahead delay, the shifter's delay line). */
typedef struct
{
    float    shifter_phase;          /* where the shifter's read heads are in their grains */
    float    shifter_dry_mix;        /* the shifter's dry share (it fades when the voice stops) */
    float    previous_pitch_hz;      /* the detector's two newest estimates */
    float    newest_pitch_hz;
    float    target_hz;              /* the scale note held */
    float    ratio_target;           /* the ratio handed to the shifter */
    float    declick_output;         /* the de-click low-pass filter's last output */
    uint32_t unvoiced_samples;       /* samples since the last reliable pitch */
} FxCarryAutotune;

/** What Pitch up and Pitch down never forget (8 B). target_ratio is set in every block. */
typedef struct
{
    float shifter_phase;             /* where the read heads are in their grains */
    float shifter_current_ratio;     /* the ratio as it glides to the target */
} FxCarryPitch;

/** One carry, exactly as it travels in FxChunk_t.carry. */
typedef struct
{
    uint8_t label;                   /* FX_RENDER_CARRY_LABEL: written by FxRender_SaveCarry */
    uint8_t mode;                    /* the AudioEffectMode it was saved from */
    uint8_t unused[2];               /* zeros: the state below starts on a 4-byte boundary */
    union
    {
        FxCarryAutotune        autotune;
        FxCarryPitch           pitch;
        AudioEffectsRobotState robot;    /* all of it (40 B): the 80 Hz oscillator never forgets */
    } state;                         /* Echo, Reverb: not used (zeros) */
} FxRenderCarry;

_Static_assert(sizeof(FxRenderCarry) == FX_RENDER_CARRY_BYTES, "one carry is FX_RENDER_CARRY_BYTES");

static void save_autotune(const AudioEffectsAutotuneState *autotune, FxCarryAutotune *carry)
{
    carry->shifter_phase     = autotune->pitch_shifter.phase;
    carry->shifter_dry_mix   = autotune->pitch_shifter.dry_mix;
    carry->previous_pitch_hz = autotune->previous_pitch_hz;
    carry->newest_pitch_hz   = autotune->newest_pitch_hz;
    carry->target_hz         = autotune->target_hz;
    carry->ratio_target      = autotune->ratio_target;
    carry->declick_output    = autotune->declick_output;
    carry->unvoiced_samples  = autotune->unvoiced_samples;
}

static void load_autotune(AudioEffectsAutotuneState *autotune, const FxCarryAutotune *carry)
{
    autotune->pitch_shifter.phase   = carry->shifter_phase;
    autotune->pitch_shifter.dry_mix = carry->shifter_dry_mix;
    autotune->previous_pitch_hz     = carry->previous_pitch_hz;
    autotune->newest_pitch_hz       = carry->newest_pitch_hz;
    autotune->target_hz             = carry->target_hz;
    autotune->ratio_target          = carry->ratio_target;
    autotune->declick_output        = carry->declick_output;
    autotune->unvoiced_samples      = carry->unvoiced_samples;
}

void FxRender_SaveCarry(const FxRender *render, uint8_t carry[FX_RENDER_CARRY_BYTES])
{
    if (carry == NULL)
    {
        return;
    }
    FxRenderCarry saved;
    memset(&saved, 0, sizeof(saved));
    if ((render != NULL) && mode_is_valid(render->effects.mode))
    {
        const AudioEffectsState *effects = &render->effects;
        saved.label = FX_RENDER_CARRY_LABEL;
        saved.mode = (uint8_t)effects->mode;
        switch (effects->mode)
        {
            case AUDIO_EFFECT_AUTOTUNE:
                save_autotune(&effects->per_mode.autotune, &saved.state.autotune);
                break;
            case AUDIO_EFFECT_PITCH_UP:
            case AUDIO_EFFECT_PITCH_DOWN:
                saved.state.pitch.shifter_phase = effects->per_mode.pitch.pitch_shifter.phase;
                saved.state.pitch.shifter_current_ratio = effects->per_mode.pitch.pitch_shifter.current_ratio;
                break;
            case AUDIO_EFFECT_ROBOT:
                saved.state.robot = effects->per_mode.robot;
                break;
            default:
                break;                  /* Echo, Reverb: nothing (the 4 s pre-roll refills them) */
        }
    }
    memcpy(carry, &saved, sizeof(saved));
}

AudioEffectsStatus FxRender_LoadCarry(FxRender *render, const uint8_t carry[FX_RENDER_CARRY_BYTES])
{
    if ((render == NULL) || (carry == NULL))
    {
        return AUDIO_EFFECTS_STATUS_NULL_POINTER;
    }
    /* A copy: carry is plain bytes in the message buffer, maybe not aligned for floats. */
    FxRenderCarry saved;
    memcpy(&saved, carry, sizeof(saved));
    /* Why refuse: another effect's numbers (or none) would be loaded into
     * this effect's fields and quietly make a wrong file. */
    if ((saved.label != FX_RENDER_CARRY_LABEL) || (saved.mode != (uint8_t)render->effects.mode))
    {
        return AUDIO_EFFECTS_STATUS_INVALID_PARAMETER;
    }
    AudioEffectsState *effects = &render->effects;
    switch (effects->mode)
    {
        case AUDIO_EFFECT_AUTOTUNE:
            load_autotune(&effects->per_mode.autotune, &saved.state.autotune);
            break;
        case AUDIO_EFFECT_PITCH_UP:
        case AUDIO_EFFECT_PITCH_DOWN:
            effects->per_mode.pitch.pitch_shifter.phase = saved.state.pitch.shifter_phase;
            effects->per_mode.pitch.pitch_shifter.current_ratio = saved.state.pitch.shifter_current_ratio;
            break;
        case AUDIO_EFFECT_ROBOT:
            effects->per_mode.robot = saved.state.robot;
            break;
        default:
            break;                      /* Echo, Reverb: nothing to load */
    }
    return AUDIO_EFFECTS_STATUS_OK;
}
